        nanes(F, "M92 132 l0 -3 l2.5 0 l0 3 M97 132 l0 -3 l2.5 0 l0 3 M102 132 l0 -3 l2.5 0 l0 3 z", "#B8B0A0") + nanes(F, "M97 150 l2 0 l0 -4 l-2 0 z M97 140 l2 0 l0 -3 l-2 0 z", "#3A3A44", .8);
      o += hrebeny(F, [[210, 6, 70, 3.5, "#8A8A58", 0]]);
