      o += hory(F, r, [[-10, 130], [80, 94], [160, 116], [250, 86], [330, 110], [410, 100]], 156, "#9AAAC0", "#5E6E8E", 110, .15);
      o += hrebeny(F, [[158, 10, 60, 1.5, "#8CB060", .05], [184, 8, 60, 3, "#98BC66", 0]]);
