const TYP = {"oblasti":{"fonologie":{"cs":"Fonologie","en":"Phonology"},"morfologie":{"cs":"Morfologie","en":"Morphology"},"slovosled":{"cs":"Slovosled","en":"Word order"},"veta":{"cs":"Větná stavba","en":"Clause structure"},"slovnik":{"cs":"Slovní zásoba","en":"Lexicon"}},"vlastnosti":[{"id":"1A","oblast":"fonologie","druh":"rada","nazev":{"cs":"Souhláskový inventář","en":"Consonant inventories"},"popis":{"cs":"Počet souhláskových fonémů jazyka. Hranice kategorií podle WALS: malý 6–14, středně malý 15–18, průměrný 19–25, středně velký 26–33, velký 34 a více.","en":"The number of consonant phonemes. WALS category limits: small 6–14, moderately small 15–18, average 19–25, moderately large 26–33, large 34 or more."},"hodnoty":{"1":{"cs":"malý (6–14)","en":"Small (6–14)"},"2":{"cs":"středně malý (15–18)","en":"Moderately small (15–18)"},"3":{"cs":"průměrný (19–25)","en":"Average (19–25)"},"4":{"cs":"středně velký (26–33)","en":"Moderately large (26–33)"},"5":{"cs":"velký (34 a více)","en":"Large (34 or more)"}},"tridy":[{"wals":[1],"cs":"malý (6–14)","en":"small (6–14)"},{"wals":[2],"cs":"středně malý (15–18)","en":"moderately small (15–18)"},{"wals":[3],"cs":"průměrný (19–25)","en":"average (19–25)"},{"wals":[4],"cs":"středně velký (26–33)","en":"moderately large (26–33)"},{"wals":[5],"cs":"velký (34 a více)","en":"large (34 or more)"}],"kapitola":1,"nazevWals":"Consonant Inventories","autor":"Ian Maddieson","pocet":546,"h":""},{"id":"2A","oblast":"fonologie","druh":"rada","nazev":{"cs":"Samohláskový inventář","en":"Vowel quality inventories"},"popis":{"cs":"Počet samohláskových kvalit bez ohledu na délku, nosovost a další rysy, které kvalitu nemění.","en":"The number of vowel qualities, disregarding length, nasalization and other features that do not change quality."},"hodnoty":{"1":{"cs":"malý (2–4 kvality)","en":"Small (2–4)"},"2":{"cs":"průměrný (5–6 kvalit)","en":"Average (5–6)"},"3":{"cs":"velký (7–14 kvalit)","en":"Large (7–14)"}},"tridy":[{"wals":[1],"cs":"malý (2–4)","en":"small (2–4)"},{"wals":[2],"cs":"průměrný (5–6)","en":"average (5–6)"},{"wals":[3],"cs":"velký (7–14)","en":"large (7–14)"}],"kapitola":2,"nazevWals":"Vowel Quality Inventories","autor":"Ian Maddieson","pocet":547,"h":""},{"id":"12A","oblast":"fonologie","druh":"rada","nazev":{"cs":"Stavba slabiky","en":"Syllable structure"},"popis":{"cs":"Nejsložitější slabika, kterou jazyk dovoluje. Jednoduchá: nejvýš jedna souhláska před samohláskou (C)V. Středně složitá: CVC nebo dvě souhlásky na začátku, z nichž druhá je likvida nebo polosamohláska. Složitá: delší shluky souhlásek.","en":"The most complex syllable a language allows. Simple: at most one consonant before the vowel, (C)V. Moderately complex: CVC, or two initial consonants the second of which is a liquid or glide. Complex: longer consonant clusters."},"hodnoty":{"1":{"cs":"jednoduchá","en":"Simple"},"2":{"cs":"středně složitá","en":"Moderately complex"},"3":{"cs":"složitá","en":"Complex"}},"tridy":[{"wals":[1],"cs":"jednoduchá","en":"simple"},{"wals":[2],"cs":"středně složitá","en":"moderately complex"},{"wals":[3],"cs":"složitá","en":"complex"}],"kapitola":12,"nazevWals":"Syllable Structure","autor":"Ian Maddieson","pocet":472,"h":""},{"id":"13A","oblast":"fonologie","druh":"rada","nazev":{"cs":"Tóny","en":"Tone"},"popis":{"cs":"Zda výška tónu rozlišuje slova nebo mluvnické tvary. Jednoduchý systém má dvě tónové úrovně, složitý tři a více nebo tónové průběhy.","en":"Whether pitch distinguishes words or grammatical forms. A simple system has two tone levels, a complex one three or more, or contour tones."},"hodnoty":{"1":{"cs":"bez tónů","en":"No tones"},"2":{"cs":"jednoduchý tónový systém","en":"Simple tone system"},"3":{"cs":"složitý tónový systém","en":"Complex tone system"}},"tridy":[{"wals":[1],"cs":"bez tónů","en":"no tones"},{"wals":[2],"cs":"jednoduchý tónový systém","en":"simple tone system"},{"wals":[3],"cs":"složitý tónový systém","en":"complex tone system"}],"kapitola":13,"nazevWals":"Tone","autor":"Ian Maddieson","pocet":510,"h":""},{"id":"19A","oblast":"fonologie","druh":"kat","nazev":{"cs":"Neobvyklé souhlásky","en":"Presence of uncommon consonants"},"popis":{"cs":"Výskyt čtyř typů souhlásek, které jsou ve světě vzácné: mlaskavek (kliků), labiovelár (současné uzávěry rty a zadní částí jazyka, [k͡p], [ɡ͡b]), faryngál a zubních frikativ („th“, [θ], [ð]).","en":"The presence of four consonant types that are rare worldwide: clicks, labial-velars (simultaneous closure at the lips and velum, [k͡p], [ɡ͡b]), pharyngeals and dental fricatives ('th', [θ], [ð])."},"hodnoty":{"1":{"cs":"žádné z nich","en":"None"},"2":{"cs":"mlaskavky","en":"Clicks"},"3":{"cs":"labioveláry","en":"Labial-velars"},"4":{"cs":"faryngály","en":"Pharyngeals"},"5":{"cs":"zubní frikativy („th“)","en":"'Th' sounds"},"6":{"cs":"mlaskavky, faryngály i „th“","en":"Clicks, pharyngeals and 'th'"},"7":{"cs":"faryngály i „th“","en":"Pharyngeals and 'th'"}},"tridy":[{"wals":[2],"cs":"mlaskavky","en":"clicks"},{"wals":[3],"cs":"labioveláry","en":"labial-velars"},{"wals":[4],"cs":"faryngály","en":"pharyngeals"},{"wals":[5],"cs":"zubní frikativy („th“)","en":"'th' sounds"},{"wals":[6,7],"cs":"více těchto typů","en":"several of these types"},{"wals":[1],"cs":"žádné z nich","en":"none","barva":"jine"}],"kapitola":19,"nazevWals":"Presence of Uncommon Consonants","autor":"Ian Maddieson","pocet":550,"h":""},{"id":"26A","oblast":"morfologie","druh":"kat","nazev":{"cs":"Předpony a přípony v ohýbání","en":"Prefixing vs. suffixing in inflectional morphology"},"popis":{"cs":"Zda jazyk vyjadřuje mluvnické kategorie (pád, osobu, čas…) spíše příponami, nebo předponami. WALS rozlišuje silnou a slabou převahu; zde jsou obě sloučené.","en":"Whether a language expresses grammatical categories (case, person, tense…) mainly with suffixes or with prefixes. WALS distinguishes strong and weak preference; here the two are merged."},"hodnoty":{"1":{"cs":"málo afixace","en":"Little affixation"},"2":{"cs":"výrazně příponový","en":"Strongly suffixing"},"3":{"cs":"mírně příponový","en":"Weakly suffixing"},"4":{"cs":"předpony a přípony stejně","en":"Equal prefixing and suffixing"},"5":{"cs":"mírně předponový","en":"Weakly prefixing"},"6":{"cs":"výrazně předponový","en":"Strongly prefixing"}},"tridy":[{"wals":[2,3],"cs":"převážně přípony","en":"mainly suffixing"},{"wals":[5,6],"cs":"převážně předpony","en":"mainly prefixing"},{"wals":[4],"cs":"předpony i přípony stejně","en":"equal prefixing and suffixing"},{"wals":[1],"cs":"málo afixace","en":"little affixation","barva":"jine"}],"kapitola":26,"nazevWals":"Prefixing vs. Suffixing in Inflectional Morphology","autor":"Matthew S. Dryer","pocet":936,"h":""},{"id":"30A","oblast":"morfologie","druh":"rada","nazev":{"cs":"Počet jmenných rodů","en":"Number of genders"},"popis":{"cs":"Počet tříd podstatných jmen, které se projevují shodou (u přídavných jmen, zájmen, sloves). Sem patří i systémy jmenných tříd, např. v bantuských jazycích.","en":"The number of noun classes reflected in agreement (on adjectives, pronouns, verbs). This includes noun-class systems such as those of Bantu languages."},"hodnoty":{"1":{"cs":"žádný","en":"None"},"2":{"cs":"dva","en":"Two"},"3":{"cs":"tři","en":"Three"},"4":{"cs":"čtyři","en":"Four"},"5":{"cs":"pět a více","en":"Five or more"}},"tridy":[{"wals":[1],"cs":"žádný","en":"none"},{"wals":[2],"cs":"dva","en":"two"},{"wals":[3],"cs":"tři","en":"three"},{"wals":[4],"cs":"čtyři","en":"four"},{"wals":[5],"cs":"pět a více","en":"five or more"}],"kapitola":30,"nazevWals":"Number of Genders","autor":"Greville G. Corbett","pocet":253,"h":""},{"id":"49A","oblast":"morfologie","druh":"rada","nazev":{"cs":"Počet pádů","en":"Number of cases"},"popis":{"cs":"Počet pádů vyjadřovaných tvary podstatných jmen (koncovkami, předponami, změnou kmene). Předložky se nepočítají. „Okrajové“ jsou jazyky, kde pádové značení existuje jen v omezené míře.","en":"The number of cases expressed in the forms of nouns (endings, prefixes, stem changes). Adpositions are not counted. 'Borderline' languages have case marking only to a limited extent."},"hodnoty":{"1":{"cs":"žádné morfologické pády","en":"No morphological case-marking"},"2":{"cs":"2 pády","en":"2 cases"},"3":{"cs":"3 pády","en":"3 cases"},"4":{"cs":"4 pády","en":"4 cases"},"5":{"cs":"5 pádů","en":"5 cases"},"6":{"cs":"6–7 pádů","en":"6–7 cases"},"7":{"cs":"8–9 pádů","en":"8–9 cases"},"8":{"cs":"10 a více pádů","en":"10 or more cases"},"9":{"cs":"jen okrajové pádové značení","en":"Exclusively borderline case-marking"}},"tridy":[{"wals":[1],"cs":"žádné","en":"none"},{"wals":[2,3],"cs":"2–3","en":"2–3"},{"wals":[4,5],"cs":"4–5","en":"4–5"},{"wals":[6],"cs":"6–7","en":"6–7"},{"wals":[7],"cs":"8–9","en":"8–9"},{"wals":[8],"cs":"10 a více","en":"10 or more"},{"wals":[9],"cs":"jen okrajové pádové značení","en":"borderline case-marking only","barva":"jine"}],"kapitola":49,"nazevWals":"Number of Cases","autor":"Oliver A. Iggesen","pocet":255,"h":""},{"id":"37A","oblast":"morfologie","druh":"kat","nazev":{"cs":"Určitý člen","en":"Definite articles"},"popis":{"cs":"Zda má jazyk určitý člen (jako anglické the) a jakou má podobu: samostatné slovo, ukazovací zájmeno v roli členu, nebo afix (například přípona v rumunštině či ve skandinávských jazycích).","en":"Whether a language has a definite article (like English the) and in what form: a separate word, a demonstrative used as an article, or an affix (such as the suffix in Romanian or the Scandinavian languages)."},"hodnoty":{"1":{"cs":"samostatné slovo odlišné od ukazovacího zájmena","en":"Definite word distinct from demonstrative"},"2":{"cs":"ukazovací zájmeno ve funkci členu","en":"Demonstrative word used as definite article"},"3":{"cs":"afix","en":"Definite affix"},"4":{"cs":"jen neurčitý člen","en":"No definite, but indefinite article"},"5":{"cs":"bez členů","en":"No definite or indefinite article"}},"tridy":[{"wals":[1],"cs":"samostatné slovo","en":"separate word"},{"wals":[2],"cs":"ukazovací zájmeno jako člen","en":"demonstrative used as article"},{"wals":[3],"cs":"afix","en":"affix"},{"wals":[4],"cs":"jen neurčitý člen","en":"indefinite article only"},{"wals":[5],"cs":"bez členů","en":"no articles","barva":"jine"}],"kapitola":37,"nazevWals":"Definite Articles","autor":"Matthew S. Dryer","pocet":597,"h":""},{"id":"38A","oblast":"morfologie","druh":"kat","nazev":{"cs":"Neurčitý člen","en":"Indefinite articles"},"popis":{"cs":"Zda má jazyk neurčitý člen (jako anglické a) a zda je shodný s číslovkou „jeden“.","en":"Whether a language has an indefinite article (like English a) and whether it is the same as the numeral 'one'."},"hodnoty":{"1":{"cs":"samostatné slovo odlišné od číslovky „jeden“","en":"Indefinite word distinct from 'one'"},"2":{"cs":"stejné slovo jako „jeden“","en":"Indefinite word same as 'one'"},"3":{"cs":"afix","en":"Indefinite affix"},"4":{"cs":"jen určitý člen","en":"No indefinite, but definite article"},"5":{"cs":"bez členů","en":"No definite or indefinite article"}},"tridy":[{"wals":[1],"cs":"odlišné od „jeden“","en":"distinct from 'one'"},{"wals":[2],"cs":"stejné jako „jeden“","en":"same as 'one'"},{"wals":[3],"cs":"afix","en":"affix"},{"wals":[4],"cs":"jen určitý člen","en":"definite article only"},{"wals":[5],"cs":"bez členů","en":"no articles","barva":"jine"}],"kapitola":38,"nazevWals":"Indefinite Articles","autor":"Matthew S. Dryer","pocet":514,"h":""},{"id":"81A","oblast":"slovosled","druh":"kat","nazev":{"cs":"Pořadí podmětu, předmětu a slovesa","en":"Order of subject, object and verb"},"popis":{"cs":"Převládající pořadí podmětu (S), předmětu (O) a slovesa (V) v oznamovací větě s plnými jmennými frázemi. Čeština je podle WALS SVO. Pořadí se slovesem na začátku (VSO, VOS) a s předmětem na začátku (OVS, OSV) jsou zde sloučená.","en":"The dominant order of subject (S), object (O) and verb (V) in declarative clauses with full noun phrases. Czech is SVO according to WALS. Verb-initial (VSO, VOS) and object-initial (OVS, OSV) orders are merged here."},"hodnoty":{"1":{"cs":"SOV","en":"SOV"},"2":{"cs":"SVO","en":"SVO"},"3":{"cs":"VSO","en":"VSO"},"4":{"cs":"VOS","en":"VOS"},"5":{"cs":"OVS","en":"OVS"},"6":{"cs":"OSV","en":"OSV"},"7":{"cs":"bez převládajícího pořadí","en":"No dominant order"}},"tridy":[{"wals":[1],"cs":"SOV","en":"SOV"},{"wals":[2],"cs":"SVO","en":"SVO"},{"wals":[3,4],"cs":"sloveso na začátku (VSO, VOS)","en":"verb-initial (VSO, VOS)"},{"wals":[5,6],"cs":"předmět na začátku (OVS, OSV)","en":"object-initial (OVS, OSV)"},{"wals":[7],"cs":"bez převládajícího pořadí","en":"no dominant order","barva":"jine"}],"kapitola":81,"nazevWals":"Order of Subject, Object and Verb","autor":"Matthew S. Dryer","pocet":1318,"h":""},{"id":"83A","oblast":"slovosled","druh":"kat","nazev":{"cs":"Pořadí předmětu a slovesa","en":"Order of object and verb"},"popis":{"cs":"Zda předmět převážně stojí před slovesem (OV), nebo za ním (VO). Patří k nejdůležitějším slovosledným parametrům, s nímž souvisí řada dalších.","en":"Whether the object mainly precedes the verb (OV) or follows it (VO). One of the most important word-order parameters, correlating with many others."},"hodnoty":{"1":{"cs":"OV","en":"OV"},"2":{"cs":"VO","en":"VO"},"3":{"cs":"bez převládajícího pořadí","en":"No dominant order"}},"tridy":[{"wals":[1],"cs":"OV","en":"OV"},{"wals":[2],"cs":"VO","en":"VO"},{"wals":[3],"cs":"bez převládajícího pořadí","en":"no dominant order","barva":"jine"}],"kapitola":83,"nazevWals":"Order of Object and Verb","autor":"Matthew S. Dryer","pocet":1454,"h":""},{"id":"85A","oblast":"slovosled","druh":"kat","nazev":{"cs":"Předložky a záložky","en":"Order of adposition and noun phrase"},"popis":{"cs":"Zda jazyk užívá předložky (před jménem, „v domě“), nebo záložky (za jménem, turecké ev için „dům pro“). Vnitřní adpozice (uvnitř jmenné fráze) jsou vzácné a patří zde k „jiným“.","en":"Whether a language uses prepositions (before the noun, 'in the house') or postpositions (after it, Turkish ev için 'house for'). Inpositions (inside the noun phrase) are rare and grouped here with 'other'."},"hodnoty":{"1":{"cs":"záložky (postpozice)","en":"Postpositions"},"2":{"cs":"předložky (prepozice)","en":"Prepositions"},"3":{"cs":"vnitřní adpozice","en":"Inpositions"},"4":{"cs":"bez převládajícího pořadí","en":"No dominant order"},"5":{"cs":"bez adpozic","en":"No adpositions"}},"tridy":[{"wals":[1],"cs":"záložky","en":"postpositions"},{"wals":[2],"cs":"předložky","en":"prepositions"},{"wals":[5],"cs":"bez adpozic","en":"no adpositions"},{"wals":[3,4],"cs":"jiné (vnitřní, bez převládajícího pořadí)","en":"other (inpositions, no dominant order)","barva":"jine"}],"kapitola":85,"nazevWals":"Order of Adposition and Noun Phrase","autor":"Matthew S. Dryer","pocet":1138,"h":""},{"id":"86A","oblast":"slovosled","druh":"kat","nazev":{"cs":"Pořadí genitivu a jména","en":"Order of genitive and noun"},"popis":{"cs":"Zda přivlastňovací (genitivní) člen stojí před řídícím jménem („Petrův dům“, angl. John's house), nebo za ním („dům Petra“).","en":"Whether the possessor (genitive) precedes the head noun (John's house) or follows it (the house of John)."},"hodnoty":{"1":{"cs":"genitiv – jméno","en":"Genitive–Noun"},"2":{"cs":"jméno – genitiv","en":"Noun–Genitive"},"3":{"cs":"bez převládajícího pořadí","en":"No dominant order"}},"tridy":[{"wals":[1],"cs":"genitiv – jméno","en":"genitive–noun"},{"wals":[2],"cs":"jméno – genitiv","en":"noun–genitive"},{"wals":[3],"cs":"bez převládajícího pořadí","en":"no dominant order","barva":"jine"}],"kapitola":86,"nazevWals":"Order of Genitive and Noun","autor":"Matthew S. Dryer","pocet":1199,"h":""},{"id":"87A","oblast":"slovosled","druh":"kat","nazev":{"cs":"Pořadí přídavného jména a jména","en":"Order of adjective and noun"},"popis":{"cs":"Zda přívlastkové přídavné jméno převážně stojí před jménem („velký dům“), nebo za ním (franc. maison blanche).","en":"Whether an attributive adjective mainly precedes the noun (big house) or follows it (French maison blanche)."},"hodnoty":{"1":{"cs":"přídavné jméno – jméno","en":"Adjective–Noun"},"2":{"cs":"jméno – přídavné jméno","en":"Noun–Adjective"},"3":{"cs":"bez převládajícího pořadí","en":"No dominant order"},"4":{"cs":"jen vnitřně řízené vztažné věty","en":"Only internally-headed relative clauses"}},"tridy":[{"wals":[1],"cs":"přídavné jméno – jméno","en":"adjective–noun"},{"wals":[2],"cs":"jméno – přídavné jméno","en":"noun–adjective"},{"wals":[3,4],"cs":"jiné (bez převládajícího pořadí)","en":"other (no dominant order)","barva":"jine"}],"kapitola":87,"nazevWals":"Order of Adjective and Noun","autor":"Matthew S. Dryer","pocet":1306,"h":""},{"id":"88A","oblast":"slovosled","druh":"kat","nazev":{"cs":"Pořadí ukazovacího zájmena a jména","en":"Order of demonstrative and noun"},"popis":{"cs":"Zda ukazovací zájmeno stojí před jménem („ten dům“), za ním, nebo je afixem připojeným ke jménu.","en":"Whether the demonstrative precedes the noun (that house), follows it, or is an affix attached to the noun."},"hodnoty":{"1":{"cs":"ukazovací zájmeno – jméno","en":"Demonstrative–Noun"},"2":{"cs":"jméno – ukazovací zájmeno","en":"Noun–Demonstrative"},"3":{"cs":"ukazovací předpona","en":"Demonstrative prefix"},"4":{"cs":"ukazovací přípona","en":"Demonstrative suffix"},"5":{"cs":"před i za jménem","en":"Demonstrative before and after noun"},"6":{"cs":"smíšené","en":"Mixed"}},"tridy":[{"wals":[1],"cs":"před jménem","en":"before the noun"},{"wals":[2],"cs":"za jménem","en":"after the noun"},{"wals":[3,4],"cs":"afix (předpona, přípona)","en":"affix (prefix, suffix)"},{"wals":[5,6],"cs":"jiné (před i za jménem, smíšené)","en":"other (both sides, mixed)","barva":"jine"}],"kapitola":88,"nazevWals":"Order of Demonstrative and Noun","autor":"Matthew S. Dryer","pocet":1172,"h":""},{"id":"98A","oblast":"veta","druh":"kat","nazev":{"cs":"Zarovnání pádového značení","en":"Alignment of case marking of full noun phrases"},"popis":{"cs":"Jak pádové tvary plných jmenných frází odlišují podmět nepřechodného slovesa (S), činitele (A) a zasažený předmět (P) přechodného slovesa. Nominativ–akuzativ: S = A ≠ P (čeština). Ergativ–absolutiv: S = P ≠ A (např. lezginština). Tripartitní: všechny tři odlišné. Aktivní–inaktivní: podmět se značí podle toho, zda děj ovládá (WALS sem řadí baskičtinu a gruzínštinu). Neutrální: bez rozlišení.","en":"How the case forms of full noun phrases distinguish the single argument of an intransitive verb (S) from the agent (A) and patient (P) of a transitive verb. Nominative–accusative: S = A ≠ P. Ergative–absolutive: S = P ≠ A (e.g. Lezgian). Tripartite: all three differ. Active–inactive: marking depends on control (WALS places Basque and Georgian here). Neutral: no distinction."},"hodnoty":{"1":{"cs":"neutrální","en":"Neutral"},"2":{"cs":"nominativ – akuzativ (standardní)","en":"Nominative–accusative (standard)"},"3":{"cs":"nominativ – akuzativ (se značeným nominativem)","en":"Nominative–accusative (marked nominative)"},"4":{"cs":"ergativ – absolutiv","en":"Ergative–absolutive"},"5":{"cs":"tripartitní","en":"Tripartite"},"6":{"cs":"aktivní – inaktivní","en":"Active–inactive"}},"tridy":[{"wals":[2,3],"cs":"nominativ – akuzativ","en":"nominative–accusative"},{"wals":[4],"cs":"ergativ – absolutiv","en":"ergative–absolutive"},{"wals":[5],"cs":"tripartitní","en":"tripartite"},{"wals":[6],"cs":"aktivní – inaktivní","en":"active–inactive"},{"wals":[1],"cs":"neutrální (bez rozlišení)","en":"neutral (no distinction)","barva":"jine"}],"kapitola":98,"nazevWals":"Alignment of Case Marking of Full Noun Phrases","autor":"Bernard Comrie","pocet":186,"h":""},{"id":"112A","oblast":"veta","druh":"kat","nazev":{"cs":"Vyjádření záporu","en":"Negative morphemes"},"popis":{"cs":"Jakým prostředkem jazyk tvoří zápor věty: afixem na slovese („ne-jdu“), zápornou částicí (angl. not), záporným pomocným slovesem (finština), nebo dvěma zápornými prvky zároveň.","en":"How a language negates a clause: with an affix on the verb, a negative particle (English not), a negative auxiliary verb (Finnish), or two negative elements at once."},"hodnoty":{"1":{"cs":"záporný afix","en":"Negative affix"},"2":{"cs":"záporná částice","en":"Negative particle"},"3":{"cs":"záporné pomocné sloveso","en":"Negative auxiliary verb"},"4":{"cs":"záporné slovo nejasné povahy","en":"Negative word, unclear if verb or particle"},"5":{"cs":"střídání záporného slova a afixu","en":"Variation between negative word and affix"},"6":{"cs":"dvojí zápor","en":"Double negation"}},"tridy":[{"wals":[1],"cs":"afix","en":"affix"},{"wals":[2],"cs":"částice","en":"particle"},{"wals":[3],"cs":"pomocné sloveso","en":"auxiliary verb"},{"wals":[6],"cs":"dvojí zápor","en":"double negation"},{"wals":[4,5],"cs":"jiné (nejasné, střídání)","en":"other (unclear, variation)","barva":"jine"}],"kapitola":112,"nazevWals":"Negative Morphemes","autor":"Matthew S. Dryer","pocet":1105,"h":""},{"id":"116A","oblast":"veta","druh":"kat","nazev":{"cs":"Zjišťovací otázky","en":"Polar questions"},"popis":{"cs":"Jak jazyk odlišuje otázku typu ano/ne od oznamovací věty: tázací částicí (pol. czy), tvarem slovesa, změnou slovosledu (podle WALS čeština a němčina: Kommst du?), nebo jen intonací (rumunština).","en":"How a language distinguishes yes/no questions from statements: with a question particle (Polish czy), verb morphology, a change of word order (German Kommst du?; WALS classes Czech here too), or intonation only (Romanian)."},"hodnoty":{"1":{"cs":"tázací částice","en":"Question particle"},"2":{"cs":"tázací tvar slovesa","en":"Interrogative verb morphology"},"3":{"cs":"částice i tvar slovesa","en":"Mixture of previous two types"},"4":{"cs":"slovosled","en":"Interrogative word order"},"5":{"cs":"absence oznamovacích morfémů","en":"Absence of declarative morphemes"},"6":{"cs":"jen intonace","en":"Interrogative intonation only"},"7":{"cs":"bez rozlišení","en":"No interrogative-declarative distinction"}},"tridy":[{"wals":[1],"cs":"částice","en":"particle"},{"wals":[2],"cs":"tvar slovesa","en":"verb morphology"},{"wals":[4],"cs":"slovosled","en":"word order"},{"wals":[6],"cs":"jen intonace","en":"intonation only"},{"wals":[3],"cs":"částice i tvar slovesa","en":"particle and verb morphology"},{"wals":[5,7],"cs":"jiné","en":"other","barva":"jine"}],"kapitola":116,"nazevWals":"Polar Questions","autor":"Matthew S. Dryer","pocet":920,"h":""},{"id":"129A","oblast":"slovnik","druh":"kat","nazev":{"cs":"Ruka a paže","en":"Hand and arm"},"popis":{"cs":"Zda jazyk pojmenovává ruku (dlaň s prsty) a paži jedním slovem, jako česká „ruka“ nebo ruská „рука“, nebo dvěma (angl. hand a arm).","en":"Whether a language names the hand and the arm with one word (as Czech ruka does) or with two (English hand and arm)."},"hodnoty":{"1":{"cs":"stejné slovo","en":"Identical"},"2":{"cs":"různá slova","en":"Different"}},"tridy":[{"wals":[1],"cs":"jedno slovo","en":"identical"},{"wals":[2],"cs":"dvě slova","en":"different"}],"kapitola":129,"nazevWals":"Hand and Arm","autor":"Cecil H. Brown","pocet":594,"h":""},{"id":"130A","oblast":"slovnik","druh":"kat","nazev":{"cs":"Prst a ruka","en":"Finger and hand"},"popis":{"cs":"Zda jazyk pojmenovává prst a ruku jedním slovem, nebo dvěma.","en":"Whether a language names the finger and the hand with one word or with two."},"hodnoty":{"1":{"cs":"stejné slovo","en":"Identical"},"2":{"cs":"různá slova","en":"Different"}},"tridy":[{"wals":[1],"cs":"jedno slovo","en":"identical"},{"wals":[2],"cs":"dvě slova","en":"different"}],"kapitola":130,"nazevWals":"Finger and Hand","autor":"Cecil H. Brown","pocet":573,"h":""},{"id":"131A","oblast":"slovnik","druh":"kat","nazev":{"cs":"Základ číselné soustavy","en":"Numeral bases"},"popis":{"cs":"Na jakém základu stojí číslovky: desítkový (jako čeština), dvacítkový (jako řada mezoamerických jazyků), jejich kombinace, soustava částí těla, nebo jen omezená řada číslovek.","en":"The base of the numeral system: decimal, vigesimal (as in many Mesoamerican languages), a mixture of the two, a body-part system, or only a restricted set of numerals."},"hodnoty":{"1":{"cs":"desítková","en":"Decimal"},"2":{"cs":"smíšená dvacítková a desítková","en":"Hybrid vigesimal-decimal"},"3":{"cs":"čistě dvacítková","en":"Pure vigesimal"},"4":{"cs":"jiný základ","en":"Other base"},"5":{"cs":"rozšířená soustava částí těla","en":"Extended body-part system"},"6":{"cs":"omezená","en":"Restricted"}},"tridy":[{"wals":[1],"cs":"desítková","en":"decimal"},{"wals":[2],"cs":"dvacítková i desítková","en":"hybrid vigesimal-decimal"},{"wals":[3],"cs":"dvacítková","en":"pure vigesimal"},{"wals":[6],"cs":"omezená","en":"restricted"},{"wals":[4,5],"cs":"jiná (jiný základ, části těla)","en":"other (other base, body parts)","barva":"jine"}],"kapitola":131,"nazevWals":"Numeral Bases","autor":"Bernard Comrie","pocet":190,"h":""},{"id":"133A","oblast":"slovnik","druh":"rada","nazev":{"cs":"Počet základních barevných kategorií","en":"Number of basic colour categories"},"popis":{"cs":"Počet základních barevných pojmů podle metodiky Berlina a Kaye (World Color Survey). Poloviční hodnoty označují kategorii, která je v jazyce jen zčásti ustálená. Angličtina, francouzština, němčina a ruština mají podle WALS 11.","en":"The number of basic colour terms following Berlin and Kay's method (World Color Survey). Half values mark a category that is only partly established. English, French, German and Russian have 11 according to WALS."},"hodnoty":{"1":{"cs":"3–4","en":"3–4"},"2":{"cs":"4,5–5,5","en":"4.5–5.5"},"3":{"cs":"6–6,5","en":"6–6.5"},"4":{"cs":"7–7,5","en":"7–7.5"},"5":{"cs":"8–8,5","en":"8–8.5"},"6":{"cs":"9–10","en":"9–10"},"7":{"cs":"11","en":"11"}},"tridy":[{"wals":[1],"cs":"3–4","en":"3–4"},{"wals":[2],"cs":"4,5–5,5","en":"4.5–5.5"},{"wals":[3],"cs":"6–6,5","en":"6–6.5"},{"wals":[4],"cs":"7–7,5","en":"7–7.5"},{"wals":[5],"cs":"8–8,5","en":"8–8.5"},{"wals":[6],"cs":"9–10","en":"9–10"},{"wals":[7],"cs":"11","en":"11"}],"kapitola":133,"nazevWals":"Number of Basic Colour Categories","autor":"Paul Kay, Luisa Maffi","pocet":116,"h":""},{"id":"138A","oblast":"slovnik","druh":"kat","nazev":{"cs":"Čaj","en":"Tea"},"popis":{"cs":"Původ slova pro čaj. Z mandarínského chá se šířilo po souši (čeština „čaj“, ruština, hindština, turečtina), z minnanského te po moři přes nizozemské obchodníky (angl. tea, něm. Tee).","en":"The origin of the word for tea. Mandarin chá spread overland (Russian chai, Hindi, Turkish), Min Nan te by sea through Dutch traders (English tea, German Tee)."},"hodnoty":{"1":{"cs":"z čínského cha","en":"Words derived from Sinitic cha"},"2":{"cs":"z minnanského te","en":"Words derived from Min Nan Chinese te"},"3":{"cs":"jiné","en":"Others"}},"tridy":[{"wals":[1],"cs":"z čínského cha","en":"from Sinitic cha"},{"wals":[2],"cs":"z minnanského te","en":"from Min Nan te"},{"wals":[3],"cs":"jiný původ","en":"other origin","barva":"jine"}],"kapitola":138,"nazevWals":"Tea","autor":"Östen Dahl","pocet":222,"h":""}]};      // typologické mapy: vybrané vlastnosti WALS, texty a hodnota pro každou tečku
let T = UI[VYCHOZI];
let denni = document.documentElement.getAttribute("data-theme") === "light";   // denní vzhled (viz níž)
let STATY = STATY_VSE[VYCHOZI];

const SKUPINY = ["ie", "st", "an", "afro", "nk", "ost"];   // pořadí je součást ověření palety
const R = Math.PI / 180;
const $ = function(id){ return document.getElementById(id); };
const bezPohybu = window.matchMedia("(prefers-reduced-motion: reduce)");
const nazevZeme = function(en){ return STATY[en] || en; };
const bezDiakritiky = function(s){ return s.toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g, ""); };
const cislo = function(n, des){
  return n.toLocaleString(T.locale, {maximumFractionDigits: des || 0, minimumFractionDigits: des || 0});
};
/* text rozhraní; ve dne má pár textů vlastní znění („bod“ místo „světélka“) s příponou Den */
function tx(klic){ return denni && T[klic + "Den"] != null ? T[klic + "Den"] : T[klic]; }
function t(klic, promenne){
  return String(tx(klic)).replace(/\{(\w+)\}/g, function(_, k){ return promenne && k in promenne ? promenne[k] : ""; });
}
function tvar(n, tvary){ /* [1, 2–4, 5+, desetinné] – čeština je potřebuje, angličtině stačí dva */
  if (!Array.isArray(tvary)) return tvary;
  if (Math.floor(n) !== n) return tvary[3] || tvary[2];     // 1,6 milionu
  if (n === 1) return tvary[0];
  if (T.lang === "cs" && n >= 2 && n <= 4 && Math.floor(n) === n) return tvary[1];
  return tvary[2];
}
function plynule(t2){ return ((t2 *= 2) <= 1 ? t2 * t2 * t2 : (t2 -= 2) * t2 * t2 + 2) / 2; }

/* ---------- mapa (smí selhat, stránka přežije) ---------- */
let ZEME = [], SOUS = null, globusOk = false;
try {
  if (typeof d3 === "undefined" || !d3.geoOrthographic) throw new Error("chybí d3-geo");
  if (typeof topojson === "undefined") throw new Error("chybí topojson");
  ZEME = topojson.feature(SVET, SVET.objects.countries).features;
  SOUS = topojson.feature(SVET, SVET.objects.land);
  globusOk = true;
} catch (e) { console.error("Glóbus se nepodařilo připravit:", e); }
const ZEME_PODLE_JMENA = {};
ZEME.forEach(function(f){ ZEME_PODLE_JMENA[f.properties.name] = f; });

/* ---------- rejstříky ---------- */
const PODLE_ID = {}, V_ZEMI = {};
JAZYKY.forEach(function(j){
  PODLE_ID[j.id] = j;
  j.zeme.forEach(function(z){ (V_ZEMI[z] = V_ZEMI[z] || []).push(j); });
});
/* texty jazyků v aktuálním jazyce rozhraní; hledat jde oběma jazyky */
function prelozData(){
  JAZYKY.forEach(function(j){
    const p = j.t[T.lang];
    j.n = p.n; j.prep = p.prep; j.rod = p.rod; j.fakt = p.fakt; j.pis = p.pis || j.pis0;
    j.hledat = bezDiakritiky([j.t.cs.n, j.t.en.n, j.dom, j.pis, j.prep, j.rod]
      .concat(j.zeme.map(function(z){ return STATY_VSE.cs[z] + " " + STATY_VSE.en[z]; })).join(" "));
  });
  REJSTRIK.rr = REJSTRIK.r[T.lang];
  REJSTRIK.mm = REJSTRIK.m[T.lang];
}
prelozData();
const B = REJSTRIK.b, POCET_B = B.length;
const bLon = new Float64Array(POCET_B), bSinLat = new Float64Array(POCET_B), bCosLat = new Float64Array(POCET_B);
const bPx = new Float32Array(POCET_B), bPy = new Float32Array(POCET_B), bVid = new Uint8Array(POCET_B);
const bHledat = new Array(POCET_B);
const radek = function(i){ return PD.radky[i] || []; };
const velke = function(s){ return s ? s.charAt(0).toUpperCase() + s.slice(1) : s; };
const sourozenci = new Map();                     // skupina → tečky, které do ní patří
for (let i = 0; i < POCET_B; i++) {
  const lat = B[i][2] * R;
  bLon[i] = B[i][1] * R; bSinLat[i] = Math.sin(lat); bCosLat[i] = Math.cos(lat);
  const nar = PD.nareci[i] ? PD.nareci[i].split("|") : [];          // hledání najde jazyk i podle jeho nářečí
  bHledat[i] = bezDiakritiky(B[i][0] + " " + (radek(i)[9] || "") + " " + nar.join(" ") + " " + nar.map(function(n){ return PD.nareciCs[n] || ""; }).join(" "));
  const sk = radek(i)[2];
  if (sk >= 0) { if (!sourozenci.has(sk)) sourozenci.set(sk, []); sourozenci.get(sk).push(i); }
}
const BEZ_RODU = new Set(REJSTRIK.nr);
const BEZ_POLOHY = new Uint8Array(REJSTRIK.b.length);    // esperanto a spol.: v seznamu jsou, na glóbu ne
REJSTRIK.bp.forEach(function(i){ BEZ_POLOHY[i] = 1; });           // umělé jazyky, pidžiny, smíšené jazyky, zvláštní mluvy: nejsou rodina
const BOD_ATLASU = {};                            // jazyk z atlasu → jeho tečka v rejstříku
for (let i = POCET_B - 1; i >= 0; i--) if (B[i][5]) BOD_ATLASU[B[i][5]] = i;
const POLOZEK_SEZNAMU = JAZYKY.length + POCET_B - Object.keys(BOD_ATLASU).length;   // jazyky atlasu + tečky bez jazyka atlasu
/* rodina a světadíl jazyka z atlasu pro řazení police; tři jazyky atlasu (srbština, chorvatština, hmongština) tečku nemají:
   rodinu vezmu z jejího českého popisu, světadíl od nejbližší tečky */
const RODINA_ATLASU = {}, OBLAST_ATLASU = {};
JAZYKY.forEach(function(j){
  const i = BOD_ATLASU[j.id];
  if (i >= 0) { RODINA_ATLASU[j.id] = B[i][3]; OBLAST_ATLASU[j.id] = B[i][4]; return; }
  RODINA_ATLASU[j.id] = REJSTRIK.r.cs.indexOf((j.t.cs.rod || "").split(" – ")[0]);
  let nej = -1, d = Infinity;
  for (let k = 0; k < POCET_B; k++) {
    const dx = (B[k][1] - j.stred[0]) * Math.cos(j.stred[1] * R), dy = B[k][2] - j.stred[1], dd = dx * dx + dy * dy;
    if (dd < d) { d = dd; nej = k; }
  }
  OBLAST_ATLASU[j.id] = nej >= 0 ? B[nej][4] : -1;
});
/* ---------- znakové jazyky: všechny / bez nich / jen ony ---------- */
const ZNAKOVY = new Uint8Array(POCET_B);
REJSTRIK.zn.forEach(function(i){ ZNAKOVY[i] = 1; });
const skryty = new Uint8Array(POCET_B);   // tečka, kterou filtr schovává
let rezimZnak = "vse", povolenych = POCET_B;
function jeZnakovyJazyk(j){ const i = BOD_ATLASU[j.id]; return i >= 0 && ZNAKOVY[i] === 1; }
/* vitalita: 0–5 = šest stupňů UNESCO (bezpečný … vymřelý), 6 = probouzený, -1 = bez údaje */
const VSECHNY_STUPNE = [0, 1, 2, 3, 4, 5, 6, -1], OHROZENE = [1, 2, 3, 4];
let povoleneStupne = new Set(VSECHNY_STUPNE);
let barvitVitalitu = false;              // tečky v barvách vitality: zapnuté tlačítkem v liště, nebo otevřený panel „Vitalita“
let typVlastnost = -1, typIzolace = -1, typTr = null;   // typologická mapa: vlastnost WALS (index do TYP.vlastnosti), zvýrazněná skupina, skupina každé tečky
function barvit(){ return barvitVitalitu || typVlastnost >= 0; }   // tečky v barvách vrstvy (vitalita nebo typologie): pevnina jednolitá, bez třpytu
let vitalitaZap = false;                 // tlačítko „Vitalita“ v liště (pamatuje se, atlas-barvy-vitality)
function promennaVitality(v){ return "var(--" + (v < 0 ? "vit-nic" : "vit-" + v) + ")"; }
function vitalitaBodu(i){ const v = radek(i)[0]; return v == null ? -1 : v; }
function atlasSkryty(j){
  const i = BOD_ATLASU[j.id];
  if (!povoleneStupne.has(i >= 0 ? vitalitaBodu(i) : -1)) return true;
  return rezimZnak === "bez" ? jeZnakovyJazyk(j) : rezimZnak === "jen" ? !jeZnakovyJazyk(j) : false;
}
function jmenoBodu(i){
  const id = B[i][5];
  if (id && PODLE_ID[id]) return PODLE_ID[id].n;
  const cs = T.lang === "cs" && radek(i)[9];
  return cs ? velke(cs) : B[i][0];
}

try { localStorage.removeItem("atlas-sbirka"); } catch (e) {}   // úklid po zrušené sbírce pozdravů

/* ---------- denní a noční vzhled: podle nastavení počítače, přepínač má přednost ---------- */
const svetlySystem = window.matchMedia("(prefers-color-scheme: light)");
function ulozenyMotiv(){ try { return localStorage.getItem("atlas-motiv"); } catch (e) { return null; } }
function obnovPrepinacMotivu(){
  $("ikona-rezim").setAttribute("href", denni ? "#i-mesic" : "#i-slunce");
  $("prepinac").setAttribute("aria-pressed", denni ? "true" : "false");
  const meta = document.querySelector('meta[name="theme-color"]');
  if (meta) meta.setAttribute("content", denni ? "#E4EEFF" : "#02030A");
}
function nastavMotiv(den){
  if (!!den === denni) return;
  denni = !!den;
  document.documentElement.setAttribute("data-theme", denni ? "light" : "dark");
  obnovPrepinacMotivu();
  obnovTexty();
  kresliHvezdy();
  if (globusOk && ctx) {
    nactiBarvy(); koule.klic = ""; koule.kandidat = ""; SVETLA = null;
    potrebaKresli = true; teckyZmeneny = true; popiskyZmeneny = true; ozivit();
  }
}
$("prepinac").addEventListener("click", function(){
  nastavMotiv(!denni);
  /* volba shodná s počítačem se nepamatuje – stránka se pak zase řídí počítačem */
  try {
    if (denni === svetlySystem.matches) localStorage.removeItem("atlas-motiv");
    else localStorage.setItem("atlas-motiv", denni ? "light" : "dark");
  } catch (e) {}
});
svetlySystem.addEventListener("change", function(){ if (!ulozenyMotiv()) nastavMotiv(svetlySystem.matches); });
obnovPrepinacMotivu();

/* ---------- police ---------- */
const seznam = $("seznam");
function tlacitko(nazev, podtitul, barva, trida){
  const tl = document.createElement("button");
  tl.type = "button"; tl.className = "jaz" + (trida ? " " + trida : "");
  if (barva) tl.style.setProperty("--r-barva", barva);
  const pruh = document.createElement("span"); pruh.className = "pruh";
  const txt = document.createElement("span"); txt.className = "txt";
  const nm = document.createElement("span"); nm.className = "nm"; nm.textContent = nazev;
  const sub = document.createElement("span"); sub.className = "sub"; sub.textContent = podtitul;
  txt.appendChild(nm); txt.appendChild(sub); tl.appendChild(pruh); tl.appendChild(txt);
  return tl;
}
/* dlaždice jazyka z atlasu: hlavní je pozdrav ve vlastním písmu, pod ním název */
function dlazdice(j){
  const tl = document.createElement("button");
  tl.type = "button"; tl.className = "jaz s-pozdravem";
  tl.style.setProperty("--r-barva", "var(--r-" + j.sk + ")");
  const pz = prvek("span", "pz", j.pis);
  if (j.kod) pz.lang = j.kod;
  tl.appendChild(pz); tl.appendChild(prvek("span", "nm", j.n));
  tl.dataset.id = j.id;
  tl.setAttribute("aria-pressed", vybrany && vybrany.typ === "atlas" && vybrany.id === j.id ? "true" : "false");
  tl.addEventListener("click", function(){ vyber(j.id); });
  return tl;
}
