    for (let n = vyber_; n; n = n.rodic) cesta.add(n);
    const druhy_ = srovnani && srovnani.b.i >= 0 ? m.podle.get(srovnani.b.i) || null : null, cesta2 = new Set();   // srovnání: cesta druhého jazyka
