      cesta.forEach(function(n){ if (n.rodic && n.ukaz) hrana(n, n.ukaz); });
      c.shadowColor = B_.rodina; c.shadowBlur = 14; c.strokeStyle = B_.rodina; c.lineWidth = 5; c.stroke();
